/* _Float128 (binary128, software arithmetic: std/c/rt/ldouble.ax) in the floating-point environment: each operation in the four
   rounding directions, its result's bits and the exceptions it raises,
   against results computed exactly and rounded by IEEE 754's rules
   (written by cmd/axiom/internal/tests/tools/gen_fenv_wide_tests.py; do not
   edit). The program prints the number of mismatches per operation. */
/* flags: --c-std=c23 */
/* native-only */
#include "print.h"
#include <fenv.h>
#include <stdio.h>
#include <string.h>

#pragma STDC FENV_ACCESS ON

typedef unsigned long long U;

struct pair {
    U alo, ahi, blo, bhi;
};

/* operation k of pair i in mode m: the result's bits (lo, hi; nan: any NaN)
   and the flags (1 invalid, 2 divide-by-zero, 4 overflow, 8 underflow, 16
   inexact) */
struct row {
    unsigned short i;
    unsigned char m, k, nan, fl;
    U lo, hi;
};

static const int modes[4] = {FE_TONEAREST, FE_DOWNWARD, FE_UPWARD, FE_TOWARDZERO};
static const char *const names[] = {"add", "sub", "mul", "div", "tod", "tof", "toh", "toll", "lt", "eq"};

static int flags(void)
{
    int f = fetestexcept(FE_ALL_EXCEPT), r = 0;
    if (f & FE_INVALID)
        r |= 1;
    if (f & FE_DIVBYZERO)
        r |= 2;
    if (f & FE_OVERFLOW)
        r |= 4;
    if (f & FE_UNDERFLOW)
        r |= 8;
    if (f & FE_INEXACT)
        r |= 16;
    feclearexcept(FE_ALL_EXCEPT);
    return r;
}
#define T _Float128

static T get(U lo, U hi)
{
    T v;
    unsigned char b[16];
    memset(&v, 0, sizeof v);
    memcpy(b, &lo, 8);
    memcpy(b + 8, &hi, 8);
    memcpy(&v, b, 16);
    return v;
}

static void bits(volatile T *p, U *lo, U *hi)
{
    unsigned char b[16];
    memset(b, 0, 16);
    memcpy(b, (const void *)p, 16);
    memcpy(lo, b, 8);
    memcpy(hi, b + 8, 8);
}

